'use strict';
const $ = (selector) => document.querySelector(selector);
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial = () => ({screen:'catalogue',role:'student',route:'recordings',subject:'Quant',session:4,offering:'Full Course',lock:false,confirmed:false,submitted:false,missing:false,access:'active',ownedAccess:'active',reading:false,read:false,completed:false,attendance:'',preview:false,scope:'session',placement:'before-video',publication:'Draft',title:'Before class: Ratios and mixtures',postTitle:'After class: Ratio practice and recap',recording:'Quant 4 · Ratios and mixtures',override:false,reason:'',audit:[],full:false,entitled:['Quant','Verbal','DI'],ownedOffering:'Full Course',previewKind:'pre',readingOrder:1,correction:false,liveDate:'2026-11-02',liveTime:'18:00'});
let s = initial();
const scenarios = [
 ['browse','Browse four recordings offerings',{screen:'catalogue'}],
 ['detail','Compare outline, price and access',{screen:'detail'}],
 ['live-catalogue','Browse live classes and availability',{screen:'catalogue',route:'live'}],
 ['full','Live registration full · 8 of 8',{screen:'detail',route:'live',full:true}],
 ['quant4','Choose Quant 4 first',{screen:'course'}],
 ['reading','Read preparation · no feedback lock',{screen:'session',reading:'pre',read:true}],
 ['watch','Watch the shared recording',{screen:'session'}],
 ['locked','Quant feedback due · subject locked',{screen:'course',lock:true}],
 ['other-subject','Verbal remains available',{screen:'course',lock:true,subject:'Verbal',session:1}],
 ['live','Registered live student · own batch',{screen:'session',route:'live'}],
 ['missed','Missed live class · feedback due',{screen:'feedback',route:'live',lock:true,completed:true}],
 ['missing','Recording unavailable · non-attendance valid',{screen:'session',route:'live',lock:true,completed:true,missing:true}],
 ['delayed','Feedback sent · awaiting confirmation',{screen:'confirmation',lock:true,submitted:true}],
 ['confirmed','Feedback confirmed · subject reopened',{screen:'confirmation',confirmed:true}],
 ['expired','Expired access · history preserved',{screen:'access',access:'expired',ownedAccess:'expired'}],
 ['unpaid','Unpurchased offering · upgrade option',{screen:'access',access:'unpaid',offering:'DI',ownedAccess:'none',entitled:[],ownedOffering:'No purchased offerings'}],
 ['editor','Admin · complete course content',{screen:'editor',role:'admin'}],
 ['preview','Admin · exact draft reading preview',{screen:'editor',role:'admin',preview:true}],
 ['publish','Admin · universal publishing scope',{screen:'publish',role:'admin',scope:'universal'}],
 ['live-admin','Admin · independent schedules & completion',{screen:'live-admin',role:'admin'}],
 ['support','Admin · feedback support & override',{screen:'support',role:'admin',lock:true,completed:true}],
 ['mocks','Existing Mocks · unchanged',{screen:'mocks'}],
 ['decisions','Review unresolved choices',{screen:'decisions'}]
];
const eligibleSubjects = () => s.offering === 'Full Course' ? ['Quant','Verbal','DI'] : [s.offering];
const sampleQ4 = () => s.subject==='Quant' && s.session===4;
const topicTitle = () => sampleQ4() ? 'Ratios and mixtures' : s.subject==='Quant' ? 'Number foundations' : s.subject==='Verbal' ? 'Reading with purpose' : 'Reading tables';
const names = {catalogue:'Explore offerings',detail:'Offering details',course:'My learning',session:'Session workspace',feedback:'Session feedback',confirmation:'Feedback status',access:'Course access',editor:'Course & content editor',publish:'Publication review','live-admin':'Live schedules',support:'Feedback support',mocks:'Existing Mocks',decisions:'Open decisions',map:'Screen map'};
const btn = (label,action,primary=false,extra='') => `<button ${action.startsWith('screen:')?`data-screen="${action.slice(7)}"`:`data-action="${action}"`} class="${primary?'primary':''}" ${extra}>${label}</button>`;
const pill = (text,kind='') => `<span class="pill ${kind}">${text}</span>`;
const notice = (title,body,kind='') => `<div class="notice ${kind}"><strong>${title}</strong><p>${body}</p></div>`;
const title = (eyebrow,heading,description,actions='') => `<div class="title-row"><div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p class="muted">${description}</p></div><div class="actions">${actions}</div></div>`;
const placements = {'before-course':'Before the course area','course-top':'At the top of the subject area','before-video':'Before the session video','after-video':'After the session video','after-course':'After the course area'};
function routeTabs(){return `<div class="tabs" aria-label="Learning route"><button data-action="route-recordings" class="${s.route==='recordings'?'selected':''}">Recordings</button><button data-action="route-live" class="${s.route==='live'?'selected':''}">Live courses</button></div>`;}
function catalogue(){return title('MAKE ROOM TO LEARN','A complete course. Your way to learn.','Build your foundation in Quant, Verbal and DI. Choose the offering and learning route that fit you.')+routeTabs()+notice(s.route==='recordings'?'Learn on your schedule':'Learn with your registered live course',s.route==='recordings'?'Browse the outline before purchase. Protected recordings open after payment; this purchase alone does not include a live registration or Meet link.':'See exact live dates and registration availability. Each live course closes at 8 students, with no session reservations or waitlist.','info')+`<div class="grid four">${['Full Course','Quant','Verbal','DI'].map((name,i)=>`<article class="card offering ${i===0?'featured':''}">${pill(i===0?'ALL THREE SUBJECTS':'INDIVIDUAL OFFERING',i===0?'':'gray')}<div class="course-number">0${i+1}</div><h2>${name}</h2><p class="muted">${i===0?'Quant + Verbal + DI':'Complete '+name+' curriculum'}</p><p>Sessions, materials, recordings and meaningful pre/post-reads.</p>${s.route==='live'?`<small>${i===1?'Registration closed · 8 / 8':'Registration open · sample availability'}</small><p>Sample start: 2 Nov · 6:00 PM IST</p>`:'<small>Choose any published session in any order.</small>'}<div class="price">${i===0?'₹25,000':'₹10,000'}</div><small>Sample catalogue quote · 6 months from payment</small><button class="${i===0?'primary':''}" data-offering="${name}">Explore ${name}</button></article>`).join('')}</div><p class="muted" style="margin-top:22px">Standalone packages: two subjects ₹18,000; three subjects ₹25,000. Three individual purchases do not become Full Course automatically. Prices here are illustrative snapshots, not a checkout quote.</p>`;}
function detail(){return title(s.route==='live'?'LIVE COURSE':'RECORDINGS OFFERING',s.offering,s.offering==='Full Course'?'One complete offering, including Quant + Verbal + DI.':'The complete '+s.offering+' course, without a shortened curriculum.',btn('Back to offerings','screen:catalogue'))+`<div class="grid split"><section class="card"><h2>Know what you will learn</h2><p class="muted">Broad outline · automatically visible with the published offering</p><div class="outline">${eligibleSubjects().map(subject=>`<p><strong>${subject}</strong> · ${subject==='Quant'?'Foundations, arithmetic, algebra and problem solving':subject==='Verbal'?'Reading comprehension and critical reasoning':'Tables, charts and multi-source reasoning'}</p>`).join('')}</div><h3>Inside a session</h3><div class="grid two"><div class="reading">Before class: ${s.offering==='Verbal'?'Reading with purpose':s.offering==='DI'?'Reading tables':'Ratios and mixtures'}<small> · Preparation reading</small></div><div class="reading">${s.offering==='Full Course'?'Quant':s.offering} 4 · Guided practice<small> · Material and shared recording</small></div></div><p>Recommended sequence is a guide. Start with ${s.offering==='Full Course'?'Quant':s.offering} 4 if that is what you need.</p>${s.route==='live'?`<h3>Independent live schedule</h3><table class="table"><tr><th>Class</th><th>Scheduled date</th></tr><tr><td>${s.offering==='Full Course'?'Quant':s.offering} 4 · Guided practice</td><td>2 November · 6:00–7:30 PM IST</td></tr><tr><td>${s.offering==='Full Course'?'Quant':s.offering} 5 · Applied practice</td><td>5 November · 6:00–7:30 PM IST</td></tr></table><p class="muted">Meet details become visible only to eligible live registrants.</p>`:''}</section><aside class="card"><h2>${s.route==='live'?'Join the live course':'Start learning with recordings'}</h2><p class="stat">${s.offering==='Full Course'?'₹25,000':'₹10,000'}</p><p>Six calendar months from successful payment.</p>${s.full?notice('Registration closed','8 of 8 places are filled. No waitlist or per-session reservation.'):notice('Demo checkout','Sign-in and payment are simulated. No transaction or account is created.','info')}<div class="actions">${btn(s.full?'Registration closed':s.route==='live'?'Simulate sign-in & registration':'Simulate sign-in & purchase','purchase',true,s.full?'disabled':'')}</div><div class="divider"></div><small>Live and recordings access are distinct. This prototype does not invent a separate route price. Full Course live seat allocation across subjects needs operational review.</small></aside></div>`;}
function course(){const locked=s.lock&&s.subject==='Quant';return title('MY LEARNING / '+s.ownedOffering,s.subject+' · Your course','Choose an available session in any order. Your outline stays open.',pill('Access active · 6 months'))+`<div class="tabs">${['Quant','Verbal','DI'].map(x=>`<button data-subject="${x}" class="${s.subject===x?'selected':''}">${x}${!s.entitled.includes(x)?' · Purchase':s.lock&&x==='Quant'?' · Feedback due':''}</button>`).join('')}</div>`+(locked?notice('Finish your Quant 4 feedback to reopen Quant','Every other Quant session is locked, including previously opened sessions. Quant 4, its materials and the outline remain available. Purchased Verbal and DI remain available.'):s.confirmed?notice('Feedback confirmed','All otherwise eligible sessions are open again.','success'):notice('Start where you need','Opening an outline or pre-read does not trigger a feedback lock.','info'))+`<div class="grid split"><section class="list">${[1,2,3,4,5].map(n=>{const block=locked&&n!==4;return `<article class="session ${n===4?'selected':''} ${block?'locked':''}"><span class="number">${String(n).padStart(2,'0')}</span><div class="grow"><h3>${s.subject} ${n} · ${s.subject==='Quant'?['Number foundations','Fractions and ratios','Mixtures','Ratios and mixtures','Percentages'][n-1]:s.subject==='Verbal'?['Reading with purpose','Argument structure','Inference practice','Critical reasoning','Passage analysis'][n-1]:['Reading tables','Chart interpretation','Data comparison','Multi-source reasoning','Case practice'][n-1]}</h3><small>${block?'Locked · Quant 4 feedback required':n===4?'Pre-read · material · recording · post-read':'Published · available'}${n===1?' · Previously opened':''}</small></div><button data-session="${n}" ${block?'disabled':''}>${block?'Locked':n===4&&locked?'Open & give feedback':'Open session'}</button></article>`}).join('')}<article class="session locked"><span class="number">06</span><div class="grow"><h3>${s.subject} 6 · Coming later</h3><small>Unpublished · not available yet</small></div><button disabled>Unavailable</button></article></section><aside class="card"><span class="eyebrow">OUTLINE HIGHLIGHTS</span><h2 style="margin-top:12px">The path, not a restriction.</h2><p>Build the foundations, connect concepts, then practise with mixed questions.</p><div class="outline"><p>01 · Foundations</p><p>02 · Guided practice</p><p>03 · Applied reasoning</p></div><p>You can start at ${s.subject} 4. The numbered outline does not enforce a sequence.</p><small>Protected content still requires publication, payment and active access.</small><div class="divider"></div>${btn('Review access','screen:access')}</aside></div>`;}
function readingView(kind='pre'){const heading=s.role==='student'&&!sampleQ4()?(kind==='post'?'After class: ':'Before class: ')+topicTitle():kind==='post'?s.postTitle:s.title;const location=kind==='post'?'After the session video':placements[s.placement];return `<div class="reading-view"><span class="eyebrow">${s.preview?'DRAFT · NOT PUBLISHED':'PUBLISHED READING'} / ${escapeHtml(location)}</span><h2>${escapeHtml(heading)}</h2><p>Prepare for <strong>${s.role==='admin'?'Quant 4 · Ratios and mixtures':s.subject+' '+s.session+' · '+topicTitle()}</strong>. ${kind==='post'?'Use this reading to recap after the session video.':'Follow the selected course placement shown above.'}</p>${s.role==='student'&&s.subject!=='Quant'?'<p>Read the example carefully, identify the main information, then explain the reasoning in your own words.</p><div class="illustration">Illustrative '+s.subject+' reading area</div>':`<p>A ratio compares quantities. Write both quantities in the <strong>same unit</strong> before simplifying.</p><div class="illustration" role="img" aria-label="Illustrative ratio diagram: two green parts and three sand parts">● ● &nbsp; : &nbsp; ○ ○ ○<br><small>2 parts concentrate : 3 parts water</small></div><blockquote>Try it: a 500 ml mixture uses a 2:3 ratio. How much is concentrate?</blockquote><a href="#ratio-example" data-action="reading-link">Jump to the worked example</a><p id="ratio-example"><strong>Worked example:</strong> 500 ÷ 5 × 2 = 200 ml.</p>`}<small>Illustrative rendered reading, including formatting, image area and link. This offline wireframe does not fetch Notion.</small></div>`;}
function session(){return title('MY LEARNING / '+s.subject,s.subject+' '+s.session+' · '+(topicTitle()),'One session, with preparation, learning and revision in one place.',btn('All sessions','screen:course'))+(s.preview?notice('Draft student preview','Fictional account and content. No progress, feedback or publication writes.','info'):'')+(s.lock&&s.subject==='Quant'?notice('Feedback required for Quant 4','This session remains open. Other Quant sessions will reopen after feedback is confirmed.'):s.read?notice('Preparation opened','Reading alone creates no feedback obligation. Other sessions are still available.','success'):'')+`<div class="grid split"><section class="card"><div class="actions" style="justify-content:space-between"><h2>Prepare for this session</h2>${pill(s.read?'Opened · visual only':'Pre-session')}</div><div class="reading"><strong>${escapeHtml(sampleQ4()?s.title:'Before class: '+topicTitle())}</strong><p class="muted">Get familiar with ratios before the worked examples.</p>${btn(s.reading?'Close reading':'Open pre-read','read')}</div>${s.reading==='pre'?readingView('pre'):''}<h2 style="margin-top:24px">Shared session recording</h2>${s.missing?notice('Recording temporarily unavailable',"You can still submit ‘I didn't attend’ and unlock Quant. Check back for the recording later."):`<div class="player"><span class="play">▶</span><strong>${escapeHtml(sampleQ4()?s.recording:s.subject+' '+s.session+' · '+topicTitle())}</strong><small>Shared asset · used by recordings and live journeys</small><div class="timeline"></div><small>Illustrative player · no playback tracking</small></div><div class="actions" style="margin-top:15px">${sampleQ4()?btn(s.confirmed?'Feedback already completed':'Simulate recording watched','watched',false,s.confirmed?'disabled':''):btn('Try the Quant 4 feedback example','scenario-watch')}</div><p class="muted"><small>Review control only. Player detection threshold is undecided: 80% or 90%. The click is not the proposed production trigger.</small></p>`}<div class="reading"><strong>Session material · ${topicTitle()} worked examples</strong><p>Published practice sheet</p>${btn('Preview sample material','material')}</div><div class="reading"><strong>${escapeHtml(sampleQ4()?s.postTitle:'After class: '+topicTitle()+' recap')}</strong><p>After the recording · practise and recap</p>${btn(s.reading==='post'?'Close post-read':'Open post-read','post-read')}</div>${s.reading==='post'?readingView('post'):''}</section><aside><section class="card"><h2>${s.route==='live'?'Your live class':'Your learning access'}</h2>${s.route==='live'?`<p>${pill('REGISTERED LIVE STUDENT')}</p><strong>${s.subject} · November evening batch</strong><p>2 November · 6:00–7:30 PM IST</p><p>${s.completed?'Class marked completed · attendance not assumed':'Scheduled live class'}</p>${btn('Join Google Meet · demo','meet',true)}<small style="display:block;margin-top:12px">Only the enrolled batch is shown. A link is needed to join; it is not needed to mark completion.</small>`:`<p>${pill('RECORDINGS ACCESS')}</p><p>No live registration or Meet details are included by this purchase alone.</p>${btn('Explore live courses','explore-live')}`}</section><section class="card" style="margin-top:20px"><h2>Feedback</h2>${s.confirmed&&sampleQ4()?`<p>${pill('Confirmed')}</p><p>Your completion is reused across live and recordings for this session.</p>`:s.lock&&sampleQ4()?`<p>One general form. The session reference is preselected.</p>${btn('Give Quant 4 feedback','screen:feedback',true)}`:'<p>Not required yet. Reading alone does not trigger feedback.</p>'}<div class="divider"></div><small>Class completion, attendance, recording availability and feedback are separate states.</small></section></aside></div>`;}
function feedback(){return title('MY LEARNING / QUANT 4','A little feedback. Then keep learning.','One general form, linked to this student and session.',btn('Back to session','screen:session'))+`<div class="grid split"><section class="card"><span class="eyebrow">GENERAL SESSION FEEDBACK · SIMULATED</span><div class="steps"><span class="active">1. Your response</span><span>2. Secure confirmation</span><span>3. Continue</span></div><div class="field"><label>Session reference · preselected and validated</label><input value="Quant 4 · Ratios and mixtures" readonly></div>${s.route==='live'?`<h3>Did you attend the live class?</h3><label class="radio"><input type="radio" name="attendance" value="attended" ${s.attendance==='attended'?'checked':''}> I attended</label><label class="radio"><input type="radio" name="attendance" value="missed" ${s.attendance==='missed'?'checked':''}> I didn't attend</label><p class="muted">Non-attendance is a valid completed response. Watching the recording is not required to unlock.</p>`:'<p>You are giving feedback on the recording. No live-attendance claim is needed.</p>'}<div class="field"><label>Illustrative question · final questions supplied by the owner</label><textarea placeholder="What helped you understand the topic? (optional sample)"></textarea></div>${btn('Simulate form submission','submit-feedback',true)}</section><aside class="card"><h2>Your response stays with this session</h2><p>The production LMS must verify the signed-in student and session securely. Changing a visible form field cannot credit another session.</p><p>Opening a form or seeing a browser success message is not proof of confirmation.</p><p>${pill('Quant 4 stays accessible','violet')}</p><p class="muted">Your recording, readings and outline remain open while confirmation is pending.</p></aside></div>`;}
function confirmation(){return title('QUANT 4 / FEEDBACK',s.confirmed?'Feedback confirmed. Keep going.':'Your feedback is being confirmed.',s.confirmed?'Your session completion has been recorded in this simulation.':'The form was sent. Keep this session open; there is no need to submit it again.')+`<div class="grid split"><section class="card"><span class="stat">${s.confirmed?'✓':'◌'}</span><h2 style="margin-top:20px">${s.confirmed?'Quant is open again':'Waiting for verified confirmation'}</h2><p>${s.confirmed?'All otherwise eligible Quant sessions are available, including previously opened sessions.':'Other Quant sessions remain locked until the LMS verifies the notification. Your current session, purchased Verbal and DI remain available.'}</p>${s.confirmed?notice('One completion across both routes','Returning to this session through live or recordings will reuse the same feedback completion.','success'):notice('If confirmation is delayed','Check status or contact support. Do not fill the same form repeatedly.','info')}<div class="actions">${s.confirmed?btn('Continue learning','screen:course',true):btn('Simulate verified notification','confirm-feedback',true)}${btn('Return to Quant 4','screen:session')}${!s.confirmed?btn('Check status','check-status')+btn('Contact support · demo','contact-support'):''}</div></section><aside class="card"><h2>Access rules still apply</h2><p>Feedback confirmation does not open unpublished content, unpaid subjects or expired access.</p><p>Duplicate notifications must be safe; they do not create duplicate completions.</p>${s.confirmed?btn('Simulate duplicate notification','duplicate'):''}</aside></div>`;}
function access(){return title('MY ACCOUNT / COURSE ACCESS',s.access==='expired'?'Your access has expired.':s.access==='unpaid'?'Add '+s.offering+' to your learning.':'Your course access','Purchase and feedback history remain separate from access eligibility.')+`<div class="grid two"><section class="card">${pill(s.access==='active'?'Active':s.access==='expired'?'Expired':'Not purchased',s.access==='active'?'':'amber')}<h2 style="margin-top:20px">${s.offering}</h2><p>${s.access==='active'?'Six calendar months of access from successful payment.':s.access==='expired'?'Protected recordings and materials are unavailable. Your payment, enrollment and feedback history remain preserved.':'This offering is visible as an upgrade option. It is not available without payment.'}</p><div class="actions">${btn('Explore eligible offerings','screen:catalogue',true)}${s.access==='active'?btn('Continue learning','screen:course'):''}</div></section><section class="card"><h2>History</h2><p>Quant 4 · Feedback confirmed</p><p>Previous enrollment retained for reference</p><small>A feedback override does not grant unpaid or expired access. Upgrade quotes and any manual access extension require the real purchase workflow.</small></section></div>`;}
function editor(){return title('ADMIN / COURSE CONTENT','A complete course, beyond the calendar.','Sessions and content do not need dates. Only actual live classes are scheduled.',btn('Review publication','screen:publish',true))+`<div class="grid split"><section class="card"><div class="grid two"><div class="field"><label for="admin-offering">Offering</label><select id="admin-offering"><option>Full Course · Quant + Verbal + DI</option><option>Individual Quant</option><option>Individual Verbal</option><option>Individual DI</option></select></div><div class="field"><label>Session</label><input value="Quant 4 · Ratios and mixtures"></div></div><div class="actions">${pill('Course session · undated','gray')}${pill(s.publication,s.publication==='Published'?'':'violet')}</div><div class="divider"></div><h2>Readings & material</h2><p class="muted">Edit meaningful student-facing titles; type labels describe placement.</p><div class="field"><label for="reading-title">Reading title</label><input id="reading-title" value="${escapeHtml(s.title)}"></div><div class="field"><label for="placement">Placement</label><select id="placement">${Object.entries(placements).map(([v,t])=>`<option value="${v}" ${s.placement===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Notion source</label><input value="Illustrative draft page · no external fetch" readonly></div><div class="actions">${btn('Preview selected draft','preview-reading',true)}${btn('Move reading down','reorder')}${btn('Add material · demo','add-material')}</div><div class="field" style="margin-top:18px"><label for="post-title">Post-read title</label><input id="post-title" value="${escapeHtml(s.postTitle)}"></div>${btn('Preview post-read draft','preview-post')}<div class="reading"><strong>Reading order · ${s.readingOrder===1?'1. '+escapeHtml(s.title)+' → 2. Ratio notation refresher':'1. Ratio notation refresher → 2. '+escapeHtml(s.title)}</strong><p>Two pre-session items. Post-session placement remains separate.</p></div><div class="divider"></div><h2>One shared recording</h2><div class="field"><label for="shared-recording">Recording title</label><input id="shared-recording" value="${escapeHtml(s.recording)}"></div><div class="scope-targets">Shared session asset Q4 · referenced by Quant recordings, Full Course and November / December live batches.</div>${btn('Save shared recording draft','save-recording')}<small style="display:block;margin-top:10px">A replacement is reviewed once and reused. It is not a per-batch upload or a class-completion action.</small></section><aside><section class="card"><h2>Draft student preview</h2><p>${pill('SIMULATION · NO STUDENT WRITES','violet')}</p><p>Exact draft title, placement and reading order. Preview does not publish or change progress / feedback.</p>${s.preview?readingView(s.previewKind):`<div class="reading"><strong>${escapeHtml(s.title)}</strong><p>${escapeHtml(placements[s.placement])} · Item ${s.readingOrder}</p>${btn('Open draft reading','preview-reading')}</div>`}<div class="actions" style="margin-top:16px">${btn('Preview render error','preview-error')}${btn('View as recordings student','student-recordings')}${btn('View as live student','student-live')}</div></section><section class="card" style="margin-top:20px"><h3>Automatic outline</h3><p>The broad outline is generated from the current course structure when the offering is published. Protected content retains its own controls.</p>${btn('Manage live schedule','screen:live-admin')}</section></aside></div>`;}
function publish(){const universal=s.scope==='universal';return title('ADMIN / PUBLICATION REVIEW','Check the content. Confirm the scope.','Draft changes do not alter the published version until confirmation.',btn('Back to editor','screen:editor'))+`<div class="grid split"><section class="card"><h2>${escapeHtml(s.title)}</h2><p>${pill(s.publication,s.publication==='Published'?'':'violet')}</p><div class="field"><label for="publish-scope">Where should this reading appear?</label><select id="publish-scope"><option value="session" ${!universal?'selected':''}>This session only · Quant 4</option><option value="universal" ${universal?'selected':''}>All applicable Quant placements · shared item</option></select></div><div class="scope-targets"><strong>Scope preview</strong><ul>${universal?'<li>Individual Quant · Quant 4</li><li>Full Course → Quant · Quant 4</li><li>November and December Quant batches · Quant 4</li>':'<li>Individual Quant · Quant 4 only</li>'}</ul><small>Relevant placements reference one shared item. This does not grant new access or create feedback obligations.</small></div><h3>Representative student placement</h3><p>${universal?'Full Course → Quant':'Individual Quant'} → Quant 4 → ${escapeHtml(placements[s.placement])}</p>${readingView()}<div class="divider"></div><label class="radio"><input id="scope-confirm" type="checkbox"> The listed scope and draft content are correct.</label><div class="actions">${btn(s.publication==='Unpublished'?'Confirm republish':'Confirm publish','publish',true)}${btn('Unpublish shared item','unpublish')}${btn('Edit draft','edit-draft')}</div></section><aside class="card"><h2>What changes?</h2><p>Only this content item and the listed placements. The session recording, other readings, live dates and attendance remain separate.</p><p>Unpublishing removes this item from the same listed student views. Its draft and audit history are retained.</p><p>Publishing an offering exposes its broad outline automatically. This item still uses its own scope confirmation.</p><small>All state changes on this screen are in-memory demonstrations.</small></aside></div>`;}
function liveAdmin(){return title('ADMIN / LIVE CLASSES','Schedule the live class. Keep content independent.','Only actual live events need dates. Each batch has its own schedule.',btn('Course content','screen:editor'))+`<div class="grid split"><section class="card"><h2>Quant 4 · November evening batch</h2><div class="grid two"><div class="field"><label>Live date</label><input type="date" id="live-date" value="${s.liveDate}"></div><div class="field"><label>Start time · IST</label><input type="time" id="live-time" value="${s.liveTime}"></div></div><div class="field"><label>Private Google Meet link</label><input placeholder="meet.google.com/... (demo only)" id="meet-link"></div><small>Stored in Admin. Disclosed only to eligible live registrants when joining. Recording-only students do not receive this link.</small><div class="actions" style="margin-top:16px">${btn('Save schedule draft','save-schedule')}${btn('Preview eligible live student','student-live')}</div><div class="divider"></div><h2>Class completion</h2><div class="grid three"><div><small>Class</small><p>${pill(s.completed?'Completed':'Scheduled')}</p></div><div><small>Recording</small><p>${pill(s.missing?'Unavailable':'Published',s.missing?'amber':'')}</p></div><div><small>Attendance</small><p>${pill('Self-reported','gray')}</p></div></div>${notice('Confirm the specific class','Quant 4 · 2 November, 6:00 PM IST · November evening batch. Marking it completed enables required feedback for its registered students. It does not claim attendance or publish a recording.','info')}<div class="actions">${btn('Mark class as completed','complete-class',true,s.completed?'disabled':'')}${btn('Correct accidental completion','reverse-completion')}</div>${s.correction?`<div class="notice info" style="margin-top:20px"><strong>Review completion correction</strong><p>Quant 4 · November evening batch · affected registered students. Existing feedback submissions will be preserved. The effect on pending subject locks is not yet decided.</p><div class="field"><label for="correction-reason">Correction reason</label><textarea id="correction-reason"></textarea></div>${btn('Record correction for review','record-correction')}<p><small>This saves a simulated review request, not an automatic lock reversal.</small></p></div>`:''}<small style="display:block;margin-top:14px">A Meet link is not required for class completion.</small></section><aside class="card"><h2>Independent schedule</h2><table class="table"><tr><th>Batch</th><th>Quant 4</th></tr><tr><td>November evening</td><td>${s.liveDate} · ${s.liveTime} IST</td></tr><tr><td>December morning</td><td>7 Dec · 9:00 AM</td></tr></table><p>Both reference the same course session and shared recording. Editing one live date does not move the other.</p><div class="divider"></div><h3>Registration</h3><p>Maximum 8 students per live course. No session reservations or waitlist.</p><p class="muted">Students see their enrolled batch only, subject to active access.</p></aside></div>`;}
function support(){return title('ADMIN / FEEDBACK SUPPORT','Resolve the lock. Preserve the history.','See confirmation status without duplicating the full response dashboard.',btn('Live classes','screen:live-admin'))+`<section class="card"><table class="table"><tr><th>Student (fictional)</th><th>Session</th><th>Feedback status</th><th>Subject gate</th><th>Access</th></tr><tr><td>Demo student A</td><td>Quant 4</td><td>${s.override?'Admin override · no submission':s.confirmed?'Confirmed':'Waiting for verified notification'}</td><td>${s.override||s.confirmed?'Released':'Quant locked'}</td><td>Active</td></tr><tr><td>Demo student B</td><td>Quant 4</td><td>Submitted · preserved</td><td>Released</td><td>Expired · still denied</td></tr></table></section><div class="grid two" style="margin-top:20px"><section class="card"><h2>Manual feedback override</h2><p><strong>Demo student A · Quant 4 · Quant subject</strong></p><p>Only the feedback restriction is affected. Payment, expiry and publication rules remain in force.</p><div class="field"><label for="override-reason">Reason · required</label><textarea id="override-reason" placeholder="Explain the support correction">${escapeHtml(s.reason)}</textarea></div><label class="radio"><input id="override-confirm" type="checkbox"> Confirm this student, session and subject.</label>${btn('Record feedback override','override',true)}<small style="display:block;margin-top:15px">A separate audit entry records Admin, time and reason. Existing submissions are not deleted or relabeled.</small></section><section class="card"><h2>Audit & confirmation</h2><div class="audit"><p>Quant 4 feedback submission · Demo student B<br><small>Preserved regardless of later corrections</small></p>${s.audit.map(a=>`<p>${escapeHtml(a)}<br><small>Demo Admin · prototype event · simulated local time</small></p>`).join('')}</div><div class="actions">${btn('Review responses in Tally · demo','tally')}${btn('Review completion reversal','reverse-completion')}</div><p class="muted">Multiple pending obligations and completion-reversal effects need a decision before production implementation.</p></section></div>`;}
function mocks(){return title('EXISTING AREA','Mocks stay as they are.','V2 course feedback locks do not change the existing Mocks experience.')+`<section class="card"><h2>Existing Mocks entry point</h2><p>This wireframe deliberately leaves mock tests, attempts, scoring and review behavior unchanged.</p><p>${pill(s.lock?'Quant feedback pending · Mocks unaffected':'No V2 changes','gray')}</p>${btn('Return to my course','screen:course',true)}</section>`;}
function decisions(){return title('REVIEW / OPEN CHOICES','Three decisions, clearly separated.','These interactions are shown for review, not silently approved.')+`<div class="grid three"><section class="card">${pill('01 · OPEN','amber')}<h2 style="margin-top:18px">Recording watched</h2><p>Feedback is due after watching. The exact player threshold is not selected: <strong>80% or 90%</strong>.</p><p>“Simulate recording watched” is a wireframe control, not a final player rule.</p></section><section class="card">${pill('02 · OPEN','amber')}<h2 style="margin-top:18px">Simultaneous obligations</h2><p>How should multiple pending session obligations in one subject be resolved and shown?</p><p>The demonstrated lock uses one pending Quant 4 obligation. No precedence or automatic clearing rule is assumed.</p></section><section class="card">${pill('03 · OPEN','amber')}<h2 style="margin-top:18px">Completion reversal</h2><p>Admin correction is approved. The effect of reversal on existing locks still needs a decision.</p><p>Preserve submissions and log the reason. This prototype does not invent an automatic unlock or erase feedback.</p></section></div><div class="notice info" style="margin-top:24px"><strong>Already settled</strong><p>One general feedback form; live completion creates the obligation for registrants; “I didn't attend” is valid completion; subject-wide lock; current session remains open; entitled other subjects remain open; support override is audited; Mocks are unchanged.</p></div>`;}
function map(){return title('REVIEW / SCREEN MAP','Walk the journey, not a slide deck.','Use the scenario selector for direct states, or click through the flows below.',`<a href="?print=1" target="_blank" rel="noopener">Open printable review pack ↗</a>`)+`<div class="grid three"><section class="card"><h2>01 · Recordings student</h2>${[['catalogue','Explore four offerings'],['detail','Outline, price and access'],['course','Choose Quant 4 first'],['session','Preparation + shared recording'],['feedback','General session feedback'],['confirmation','Delayed / confirmed state'],['access','Unpaid and expired access']].map(([a,b])=>`<button class="screen-link" data-screen="${a}">${b}<small>${names[a]}</small></button>`).join('')}</section><section class="card"><h2>02 · Live student</h2><p>Browse availability → sign in/register → own batch → eligible Meet access → completed class → attendance response → confirmation.</p>${btn('Start registered live scenario','scenario-live',true)}<div class="divider"></div>${btn('Missed class + no recording','scenario-missing')}<p class="muted">Non-attendance unlocks after verified submission, without requiring a recording watch.</p>${btn('Registration full','scenario-full')}</section><section class="card"><h2>03 · Admin</h2>${[['editor','Course content & reading preview'],['publish','Individual / universal publication'],['live-admin','Schedules & class completion'],['support','Feedback support & audit']].map(([a,b])=>`<button class="screen-link" data-screen="${a}">${b}</button>`).join('')}<div class="divider"></div>${btn('Open review decisions','screen:decisions')}</section></div>`;}
const screens={catalogue,detail,course,session,feedback,confirmation,access,editor,publish,'live-admin':liveAdmin,support,mocks,decisions,map};
function render(){const admin=s.role==='admin';$('#mode').innerHTML=`<button data-action="mode-student" class="${!admin?'selected':''}">Student</button><button data-action="mode-admin" class="${admin?'selected':''}">Admin</button>`;$('#nav').innerHTML=(admin?[['editor','Course content'],['publish','Publication review'],['live-admin','Live schedules'],['support','Feedback support'],['mocks','Mocks · unchanged']]:[['catalogue','Explore offerings'],['course','My learning'],['session','Current session'],['access','My access'],['mocks','Mocks · unchanged']]).map(([screen,label])=>`<button data-screen="${screen}" class="${s.screen===screen?'selected':''}">${label}</button>`).join('');$('#persona').innerHTML=(admin?'Demo Admin':'Demo student')+'<small style="display:block">Fictional review account</small>';$('#breadcrumb').textContent=(admin?'Admin workspace':'Student workspace')+' / '+names[s.screen];$('#content').innerHTML=screens[s.screen]();}
function loadScenario(id){const row=scenarios.find(x=>x[0]===id);if(!row)return;s={...initial(),...row[2]};$('#scenario').value=id;render();}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500);}
function go(screen){if(s.role==='student'&&['course','session'].includes(screen)&&s.ownedAccess==='active'){s.access='active';if(!s.entitled.includes(s.subject))s.subject=s.entitled[0];}if(s.role==='student'&&['course','session','feedback','confirmation'].includes(screen)&&s.ownedAccess!=='active'){s.screen='access';render();toast('Protected course access requires a paid, active entitlement.');return;}if(s.role==='student'&&screen==='session'&&s.lock&&s.subject==='Quant'&&s.session!==4){s.screen='course';render();toast('Quant 4 feedback is required before opening another Quant session.');return;}if(['editor','publish','live-admin','support'].includes(screen))s.role='admin';s.screen=screen;render();window.scrollTo(0,0);}
const actions={
 reset:()=>loadScenario('browse'),
 'mode-student':()=>{s.role='student';go('course');},'mode-admin':()=>{s.role='admin';go('editor');},
 'route-recordings':()=>{s.route='recordings';render();},'route-live':()=>{s.route='live';render();},
 purchase:()=>{s.access='active';s.ownedAccess='active';s.entitled=eligibleSubjects();s.ownedOffering=s.offering;s.subject=s.entitled[0];s.session=4;s.role='student';go('course');toast('Demo purchase complete. No real payment or enrollment.');},
 read:()=>{s.read=true;s.reading=s.reading==='pre'?false:'pre';render();},
 'post-read':()=>{s.read=true;s.reading=s.reading==='post'?false:'post';render();},
 watched:()=>{if(s.confirmed){toast('Feedback already completed for this session.');return;}s.lock=true;go('feedback');},
 'submit-feedback':()=>{if(s.route==='live'&&!s.attendance){toast('Choose whether you attended the live class.');return;}s.submitted=true;go('confirmation');},
 'confirm-feedback':()=>{s.confirmed=true;s.lock=false;render();toast('Verified notification simulated. Quant feedback lock released.');},
 duplicate:()=>toast('Duplicate ignored in this simulation. Existing confirmation is preserved.'),
 'check-status':()=>toast('Still awaiting verification. No need to submit again.'),
 'contact-support':()=>toast('Support handoff simulated: student + Quant 4 reference included.'),
 'explore-live':()=>{s.route='live';go('catalogue');},meet:()=>toast('Demo Meet join action. No external meeting opens.'),
 material:()=>toast('Sample material preview: Ratios worked examples. No download or progress write.'),
 'reading-link':()=>{document.querySelector('#ratio-example')?.scrollIntoView({behavior:'smooth',block:'center'});},
 'preview-reading':()=>{s.title=$('#reading-title')?.value??s.title;s.postTitle=$('#post-title')?.value??s.postTitle;if(!s.title.trim()){toast('Give the reading a meaningful title before previewing.');return;}s.preview=true;s.previewKind='pre';render();},
 'preview-error':()=>{s.preview=false;render();const box=document.createElement('div');box.className='notice';box.setAttribute('role','alert');box.innerHTML='<strong>Reading could not be rendered</strong><p>Check the Notion source and try the preview again. An external link alone does not confirm rendering.</p>';$('#content .grid>aside .card').prepend(box);},
 reorder:()=>{s.title=$('#reading-title').value;s.postTitle=$('#post-title').value;s.readingOrder=s.readingOrder===1?2:1;render();toast('Pre-session reading order updated in this draft.');},
 'preview-post':()=>{s.title=$('#reading-title').value;s.postTitle=$('#post-title').value;if(!s.postTitle.trim()){toast('Give the post-read a meaningful title.');return;}s.preview=true;s.previewKind='post';render();},
 'add-material':()=>toast('New material draft simulated. Session content remains undated.'),
 'save-recording':()=>{s.recording=$('#shared-recording').value;s.publication='Draft';s.audit.push('Shared recording draft edited; references preserved.');toast('Shared asset draft saved locally. Review scope before publication.');},
 'student-recordings':()=>{s.role='student';s.route='recordings';s.screen='session';s.preview=true;render();toast('Draft student simulation. No real student progress or feedback changes.');},
 'student-live':()=>{s.role='student';s.route='live';s.screen='session';s.preview=true;render();toast('Eligible live-student simulation. No real account is impersonated.');},
 publish:()=>{if(!$('#scope-confirm').checked){toast('Confirm the displayed scope before publishing.');return;}s.publication='Published';s.audit.push('Content published to '+s.scope+' scope.');render();toast('Publication simulated. Broad offering outline and protected item controls stay separate.');},
 unpublish:()=>{if(!$('#scope-confirm').checked){toast('Review and confirm the scope before unpublishing.');return;}s.publication='Unpublished';s.audit.push('Content unpublished from '+s.scope+' scope; history retained.');render();toast('Unpublished in this prototype. Draft and history retained.');},
 'edit-draft':()=>{s.publication='Draft';go('editor');},
 'save-schedule':()=>{s.liveDate=$('#live-date').value;s.liveTime=$('#live-time').value;if(!s.liveDate||!s.liveTime){toast('A live class needs an exact date and start time.');return;}render();toast('November batch draft updated. December schedule is unchanged.');},
 'complete-class':()=>{s.completed=true;s.lock=true;s.audit.push('Quant 4 November class marked complete; feedback due for registered students.');render();toast('Completion simulated. Attendance and recording state unchanged.');},
 'reverse-completion':()=>{s.correction=true;go('live-admin');},
 'record-correction':()=>{const reason=$('#correction-reason').value.trim();if(!reason){toast('Enter a reason for the correction review.');return;}s.audit.push(new Date().toISOString()+' · Completion correction requested for Quant 4 / November batch · '+reason+' · Existing submissions preserved; lock consequences awaiting decision.');s.correction=false;go('support');toast('Correction review recorded in simulation. Completion and lock state are unchanged pending the decision.');},
 override:()=>{s.reason=$('#override-reason').value.trim();if(!s.reason||!$('#override-confirm').checked){toast('Enter a reason and confirm the student/session/subject.');return;}s.override=true;s.lock=false;s.audit.push(new Date().toISOString()+' · Feedback override · Demo student A / Quant 4 / Quant · Reason: '+s.reason);render();toast('Override recorded separately. Existing submissions and access rules preserved.');},
 tally:()=>toast('External response review is simulated. No Tally account or data is accessed.'),
 'scenario-watch':()=>loadScenario('watch'),'scenario-live':()=>loadScenario('live'),'scenario-missing':()=>loadScenario('missing'),'scenario-full':()=>loadScenario('full')
};
document.addEventListener('click',(e)=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.screen){e.preventDefault();go(target.dataset.screen);}else if(target.dataset.action){e.preventDefault();actions[target.dataset.action]?.();}else if(target.dataset.offering){s.offering=target.dataset.offering;s.full=s.route==='live'&&s.offering==='Quant';go('detail');}else if(target.dataset.subject){if(!s.entitled.includes(target.dataset.subject)){s.offering=target.dataset.subject;s.access='unpaid';go('access');}else{s.subject=target.dataset.subject;s.session=s.subject==='Quant'?4:1;render();}}else if(target.dataset.session){s.session=Number(target.dataset.session);s.reading=false;go('session');}});
document.addEventListener('change',(e)=>{if(e.target.id==='scenario')loadScenario(e.target.value);if(e.target.name==='attendance')s.attendance=e.target.value;if(e.target.id==='placement'){s.title=$('#reading-title').value;s.placement=e.target.value;render();}if(e.target.id==='publish-scope'){s.scope=e.target.value;render();}});
$('#scenario').innerHTML=scenarios.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
if(new URLSearchParams(location.search).has('print')){document.body.classList.add('print-pack');document.body.innerHTML=`<div class="print-cover"><span class="eyebrow">ACE CLUB LMS V2 · 28 OCTOBER 2026</span><h1>Full courses.<br>Clear learning journeys.</h1><p>Desktop wireframes · Student recordings, registered live courses and Admin workflows.</p><p>Every action and content example is simulated. This pack is design evidence, not a claim of production functionality.</p><p><strong>Open decisions:</strong> recording watch threshold, simultaneous obligations, completion reversal effects.</p><p>Open index.html for the clickable prototype and screen map.</p></div>`+scenarios.map(([,label,state],i)=>{s={...initial(),...state};return `<article class="print-screen"><div class="print-label">${String(i+1).padStart(2,'0')} / ${label} · WIREFRAME</div>${screens[s.screen]()}</article>`}).join('');}else render();
